TELEMETRY_SIGNED_FIELDS = TELEMETRY_FIELDS | {"keyVersion", "signature"}
SIGNATURE_PATTERN = re.compile(r"[0-9a-f]{128}")
EVALUATION_FIELDS = {"from", "to"}
FUND_FIELDS = {"amountMicros", "reference"}
SETTLEMENT_FIELDS = {"slaId", "evaluationSeq"}
