EVALUATION_QUERY_PARAMS = {"limit", "cursor"}
SETTLEMENT_QUERY_PARAMS = {"limit", "cursor"}
LEDGER_QUERY_PARAMS = {"limit", "cursor"}
DISPUTE_EVENTS_QUERY_PARAMS = {"limit", "cursor"}
DISPUTE_EVIDENCE_QUERY_PARAMS = {"limit", "cursor"}
